fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    if n == 0 || n == 1 {
        return numbers;
    }

    // Pre-allocate a vector with the needed capacity for efficiency.
    let mut result = Vec::with_capacity(2 * n - 1);

    for (i, &num) in numbers.iter().enumerate() {
        result.push(num);
        // Insert delimiter after each element except the last
        if i != n - 1 {
            result.push(delimiter);
        }
    }

    result
}